mapper.select:
select id, name from course



  where is_in_progress = #{inProgressType}



order by is_in_progress desc, end_date desc

select c.id, c.name from course c join staff_assignment sa on c.id = sa.course_id join user u on u.id = sa.user_id

where u.id = #{loginUser.id}



  and is_in_progress = #{inProgressType}



order by c.is_in_progress desc, c.end_date desc

select es.id, c.is_in_progress, c.name, instructor.fullname as instructor_fullname, learner.fullname as learner_fullname, es.employment_status from course c join staff_assignment sa on sa.course_id = c.id join user instructor on instructor.id = sa.user_id and instructor.type = 'INSTRUCTOR' join learner_enrollment le on le.course_id = c.id join user learner on learner.id = le.user_id join employment_support es on es.learner_enrollment_id = le.id
c.is_in_progress = #{firstCategory}
c.id = #{secondCategory}
and learner.fullname like concat('%', #{keyword}, '%')
order by c.is_in_progress desc, c.end_date desc limit #{skip}, #{pagingSize}

select count(*) from course c join staff_assignment sa on sa.course_id = c.id join user instructor on instructor.id = sa.user_id and instructor.type = 'INSTRUCTOR' join learner_enrollment le on le.course_id = c.id join user learner on learner.id = le.user_id join employment_support es on es.learner_enrollment_id = le.id
c.is_in_progress = #{firstCategory}
c.id = #{secondCategory}
and learner.fullname like concat('%', #{keyword}, '%')
